// Normalize Vapi/Retell payload into a canonical shape
// Vapi end-of-call-report: $json.message.call.customer.number + transcript
// Retell call_ended:        $json.call.from_number + transcript
// Adjust the two extractors below to match YOUR provider.

const body = $input.first().json;

// --- Vapi shape (default) ---
let callerPhone = body?.message?.call?.customer?.number;
let transcript = body?.message?.transcript ?? body?.message?.artifact?.transcript;
let callId = body?.message?.call?.id;

// --- Retell fallback ---
if (!callerPhone) callerPhone = body?.call?.from_number;
if (!transcript) transcript = body?.call?.transcript;
if (!callId) callId = body?.call?.call_id;

if (!callerPhone) {
  // Unknown caller (no phone in payload). Still let the agent answer, but
  // skip the memory lookup. The downstream IF branches on this flag.
  return [{ json: { callerPhone: null, transcript, callId, hasPhone: false } }];
}

// E.164-ish normalization: strip spaces, parens, dashes; keep leading +
const normalized = String(callerPhone).replace(/[\s\(\)\-]/g, '');

return [{
  json: {
    callerPhone: normalized,
    transcript: transcript ?? '',
    callId: callId ?? '',
    hasPhone: true,
    receivedAt: new Date().toISOString(),
  },
}];

// Build a plain-text context block the LLM can read.
// Both branches converge here; pick whichever has data.

const transcript = $('Normalize Payload').item.json.transcript || '(no transcript)';
const callerPhone = $('Normalize Payload').item.json.callerPhone || 'unknown';

// Pull recent memory results if the caller was known
let contextLines = [];
try {
  const memSearch = $('Memory: Recent Context').first()?.json;
  const results = memSearch?.results ?? memSearch?.data?.results ?? [];
  contextLines = results.slice(0, 5).map((r, i) => {
    const text = r.content ?? r.text ?? r.formatted ?? JSON.stringify(r).slice(0, 200);
    return `${i + 1}. ${text}`;
  });
} catch (e) {
  // First-time caller path — no prior memory to summarize
  contextLines = ['(this is a new caller — no prior interactions on file)'];
}

const contextBlock = contextLines.length
  ? contextLines.join('\n')
  : '(no relevant prior context)';

return [{
  json: {
    callerPhone,
    transcript,
    contextBlock,
    systemPrompt: `You are a friendly voice agent for a small business.\n\nCaller phone: ${callerPhone}\n\nWhat we know about this caller from prior calls:\n${contextBlock}\n\nReply concisely (under 60 words) and reference past context when relevant.`,
  },
}];
